CREATE TABLE IF NOT EXISTS catalogo.proveedores_catalogo(tenant_id uuid NOT NULL REFERENCES plataforma.tenants(id),tercero_id uuid NOT NULL,codigo text NOT NULL CHECK(length(btrim(codigo)) BETWEEN 1 AND 80),estado text NOT NULL DEFAULT 'ACTIVE' CHECK(estado IN ('ACTIVE','INACTIVE','BLOCKED')),contacto jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(contacto)='object'),condiciones jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(condiciones)='object'),creado_por uuid NOT NULL REFERENCES plataforma.users(id),creado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),actualizado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,tercero_id),UNIQUE(tenant_id,codigo),FOREIGN KEY(tenant_id,tercero_id) REFERENCES catalogo.terceros(tenant_id,id));
CREATE TABLE IF NOT EXISTS catalogo.producto_proveedores(tenant_id uuid NOT NULL,producto_id uuid NOT NULL,tercero_id uuid NOT NULL,codigo_proveedor text,costo administracion.importe,plazo_dias integer CHECK(plazo_dias IS NULL OR plazo_dias BETWEEN 0 AND 3650),preferido boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant_id,producto_id,tercero_id),FOREIGN KEY(tenant_id,producto_id) REFERENCES catalogo.productos(tenant_id,id),FOREIGN KEY(tenant_id,tercero_id) REFERENCES catalogo.proveedores_catalogo(tenant_id,tercero_id));
ALTER TABLE catalogo.proveedores_catalogo ENABLE ROW LEVEL SECURITY;ALTER TABLE catalogo.producto_proveedores ENABLE ROW LEVEL SECURITY;REVOKE ALL ON catalogo.proveedores_catalogo,catalogo.producto_proveedores FROM PUBLIC,mastererp_app;
INSERT INTO plataforma.permissions(code,description) VALUES('catalog.suppliers.read','Read Catalog suppliers'),('catalog.suppliers.write','Create and update Catalog suppliers') ON CONFLICT(code) DO NOTHING;
CREATE OR REPLACE FUNCTION catalogo.proveedores_leer(p_id uuid DEFAULT NULL,p_estado text DEFAULT NULL,p_limit integer DEFAULT 100) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,pg_temp AS $$ DECLARE result jsonb;BEGIN IF p_limit NOT BETWEEN 1 AND 101 THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.suppliers.read') IS NOT TRUE THEN RAISE EXCEPTION 'Supplier access denied' USING ERRCODE='42501';END IF;SELECT COALESCE(jsonb_agg(item ORDER BY nombre,id),'[]') INTO result FROM(SELECT t.nombre,t.id,jsonb_build_object('id',t.id,'code',s.codigo,'name',t.nombre,'status',s.estado,'contact',s.contacto,'terms',s.condiciones,'version',s.version,'updated_at',s.actualizado_en) item FROM catalogo.proveedores_catalogo s JOIN catalogo.terceros t ON(t.tenant_id,t.id)=(s.tenant_id,s.tercero_id) WHERE s.tenant_id=plataforma.current_app_tenant_id() AND(p_id IS NULL OR s.tercero_id=p_id)AND(p_estado IS NULL OR s.estado=p_estado)ORDER BY t.nombre,t.id LIMIT p_limit)q;IF p_id IS NOT NULL AND jsonb_array_length(result)=0 THEN RAISE EXCEPTION 'Supplier not found' USING ERRCODE='P0002';END IF;RETURN CASE WHEN p_id IS NULL THEN result ELSE result->0 END;END $$;
CREATE OR REPLACE FUNCTION catalogo.proveedor_crear(p_codigo text,p_nombre text,p_contacto jsonb,p_condiciones jsonb,p_key varchar) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,auditoria,pg_temp AS $$ DECLARE actor uuid:=plataforma.current_app_user_id();tenant uuid:=plataforma.current_app_tenant_id();op text:='catalog.suppliers.create';corr uuid;fp text;cached plataforma.idempotency_keys%ROWTYPE;party uuid:=gen_random_uuid();response jsonb;BEGIN IF length(btrim(p_codigo)) NOT BETWEEN 1 AND 80 OR length(btrim(p_nombre)) NOT BETWEEN 1 AND 200 OR jsonb_typeof(COALESCE(p_contacto,'{}'))<>'object' OR jsonb_typeof(COALESCE(p_condiciones,'{}'))<>'object' OR length(p_key) NOT BETWEEN 1 AND 128 THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.suppliers.write') IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'') IS DISTINCT FROM op THEN RAISE EXCEPTION 'Supplier creation denied' USING ERRCODE='42501';END IF;corr:=NULLIF(current_setting('app.correlation_id',true),'')::uuid;fp:=encode(public.digest(jsonb_build_array(p_codigo,p_nombre,p_contacto,p_condiciones)::text,'sha256'),'hex');PERFORM pg_advisory_xact_lock(hashtextextended(p_key,0));SELECT * INTO cached FROM plataforma.idempotency_keys WHERE idempotency_key=p_key;IF FOUND THEN IF cached.actor_user_id<>actor OR cached.request_tenant_id<>tenant OR cached.operation<>op OR cached.request_fingerprint<>fp THEN RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='23505';END IF;RETURN cached.response_payload;END IF;INSERT INTO catalogo.terceros(id,tenant_id,codigo,nombre)VALUES(party,tenant,p_codigo,btrim(p_nombre));INSERT INTO catalogo.roles_tercero VALUES(tenant,party,'proveedor');INSERT INTO catalogo.proveedores_catalogo(tenant_id,tercero_id,codigo,contacto,condiciones,creado_por)VALUES(tenant,party,p_codigo,COALESCE(p_contacto,'{}'),COALESCE(p_condiciones,'{}'),actor);response:=catalogo.proveedores_leer(party);INSERT INTO plataforma.idempotency_keys(idempotency_key,actor_user_id,operation,resource_id,request_fingerprint,request_tenant_id,response_payload)VALUES(p_key,actor,op,party,fp,tenant,response);INSERT INTO auditoria.events(tenant_id,actor_user_id,module_code,entity_type,entity_id,action,correlation_id,metadata)VALUES(tenant,actor,'2.1.5-suppliers','tercero',party,op,corr,'{}');RETURN response;END $$;
CREATE OR REPLACE FUNCTION catalogo.proveedor_actualizar(p_id uuid,p_version bigint,p_cambios jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,auditoria,pg_temp AS $$ DECLARE tenant uuid:=plataforma.current_app_tenant_id();actor uuid:=plataforma.current_app_user_id();current catalogo.proveedores_catalogo%ROWTYPE;corr uuid;key text;BEGIN IF p_version IS NULL OR jsonb_typeof(p_cambios)<>'object' OR p_cambios='{}' THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;FOR key IN SELECT jsonb_object_keys(p_cambios) LOOP IF key NOT IN('name','status','contact','terms')THEN RAISE EXCEPTION 'Unsupported supplier field' USING ERRCODE='22023';END IF;END LOOP;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.suppliers.write') IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'') IS DISTINCT FROM 'catalog.suppliers.update' THEN RAISE EXCEPTION 'Supplier update denied' USING ERRCODE='42501';END IF;SELECT * INTO current FROM catalogo.proveedores_catalogo WHERE tenant_id=tenant AND tercero_id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Supplier not found' USING ERRCODE='P0002';END IF;IF current.version<>p_version THEN RAISE EXCEPTION 'Stale supplier version' USING ERRCODE='40001';END IF;IF p_cambios?'name' THEN UPDATE catalogo.terceros SET nombre=btrim(p_cambios->>'name'),version=version+1 WHERE tenant_id=tenant AND id=p_id;END IF;UPDATE catalogo.proveedores_catalogo SET estado=CASE WHEN p_cambios?'status' THEN p_cambios->>'status' ELSE estado END,contacto=CASE WHEN p_cambios?'contact' THEN p_cambios->'contact' ELSE contacto END,condiciones=CASE WHEN p_cambios?'terms' THEN p_cambios->'terms' ELSE condiciones END,version=version+1,actualizado_en=transaction_timestamp() WHERE tenant_id=tenant AND tercero_id=p_id;corr:=NULLIF(current_setting('app.correlation_id',true),'')::uuid;INSERT INTO auditoria.events(tenant_id,actor_user_id,module_code,entity_type,entity_id,action,correlation_id,metadata)VALUES(tenant,actor,'2.1.5-suppliers','tercero',p_id,'catalog.suppliers.update',corr,'{}');RETURN catalogo.proveedores_leer(p_id);END $$;
REVOKE ALL ON FUNCTION catalogo.proveedores_leer(uuid,text,integer),catalogo.proveedor_crear(text,text,jsonb,jsonb,varchar),catalogo.proveedor_actualizar(uuid,bigint,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION catalogo.proveedores_leer(uuid,text,integer),catalogo.proveedor_crear(text,text,jsonb,jsonb,varchar),catalogo.proveedor_actualizar(uuid,bigint,jsonb) TO mastererp_app;
